def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    if mode not in ("READ", "WRITE"):
        raise ValueError("Mode must be 'READ' or 'WRITE'")
    if not bookmarks:
        bookmarks = []
    if not metadata:
        metadata = {}
    if timeout is not None and timeout <= 0:
        raise ValueError("Timeout must be a positive integer")
    if db and not isinstance(db, str):
        raise ValueError("Database name must be a string")
    if imp_user and not isinstance(imp_user, str):
        raise ValueError("Impersonated user must be a string")
    if dehydration_hooks and not isinstance(dehydration_hooks, dict):
        raise ValueError("Dehydration hooks must be a dict")
    if hydration_hooks and not isinstance(hydration_hooks, dict):
        raise ValueError("Hydration hooks must be a dict")
    if not handlers:
        handlers = {}

    begin_message = BeginMessage(
        mode,
        bookmarks,
        metadata,
        timeout,
        db,
        imp_user,
        dehydration_hooks,
        hydration_hooks,
    )
    self._append_message(begin_message)
    return Response(begin_message, handlers)
