    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        use_count = {}

        def wrapper(*args, **kwargs):
            if typed:
                key = args[0]
            else:
                key = make_key(args, kwargs)
            if key in cache:
                use_count[key] += 1
                wrapper.hits += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if len(cache) >= maxsize:
                    for k, v in use_count.items():
                        if v == 1:
                            del cache[k]
                            del use_count[k]
                            break
                use_count[key] = 1
                wrapper.misses += 1
                cache[key] = result
                return result
        def cache_info():
            """Report cache statistics"""
            return f"Hits: {wrapper.hits}, misses: {wrapper.misses}, maxsize: {maxsize}, currsize: {len(cache)}"
        wrapper.hits = 0
        wrapper.misses = 0
        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache.clear
        return wrapper
    return decorator
