            raise ValueError("Inventory spec_version not supported")

    # Otherwise, use the spec_version from the class
    else:
        spec_version = self.spec_version
        if spec_version == "1.0":
            self._validate_v1_0(inventory)
        elif spec_version == "1.1":
            self._validate_v1_1(inventory)
        else:
            raise ValueError("Inventory spec_version not supported")

def _validate_v1_0(self, inventory):
    """Validate a given inventory against the v1.0 spec."""
    # Check for required keys
    required_keys = ["type", "name", "folder", "dependencies"]
    if not all(key in inventory for key in required_keys):
        raise ValueError("Inventory v1.0 must contain the following keys: " + ", ".join(required_keys))

    # Check that type is a string
    if not isinstance(inventory["type"], str):
