    # Check that dependencies is a list
    if not isinstance(inventory["dependencies"], list):
        raise TypeError("Inventory v1.0 dependencies must be a list")

    # Check that all dependencies are strings
    for dependency in inventory["dependencies"]:
        if not isinstance(dependency, str):
