def _validate_v1_1(self, inventory):
    """Validate a given inventory against the v1.1 spec."""
    # Check for required keys
    required_keys = ["type", "name", "folder", "dependencies", "version"]
    if not all(key in inventory for key in required_keys):
        raise ValueError("Inventory v1.1 must contain the following keys: " + ", ".join(required_keys))

    # Check that type is a string
    if not isinstance(inventory["type"], str):
