def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check that all parameters in prior are present in self, and that their values
    # are not different from those in self.
    if self.parameters:
        for prior_param in prior.parameters:
            if prior_param not in self.parameters:
                raise ValueError(f'{prior_param} is not present in {self}')
            if prior.get_value(prior_param) != self.get_value(prior_param):
                raise ValueError(f'parameter {prior_param} has value {prior.get_value(prior_param)} in {prior} but value {self.get_value(prior_param)} in {self}')

    # Check that all species in prior are also present in self.
    if self.species:
        for prior_species in prior.species:
            if prior_species not in self.species:
                raise ValueError(f'{prior_species} is not present in {self}')

    # Check that the stoichiometry matrix of prior is a valid submatrix of the
    # stoichiometry matrix of self.
    if self.stoichiometry_matrix:
        prior_stoichiometry_matrix = prior.stoichiometry_matrix
        if np.abs(prior_stoichiometry_matrix - self.stoichiometry_matrix).max() > 1e-10:
            raise ValueError(f'{prior.stoichiometry_matrix} is not a submatrix of {self.stoichiometry_matrix}')

    # Check that the propensities of prior are generally less than those of self
    # for any rate constant that is present in both.
    if self.propensities:
        for prior_propensity in prior.propensities:
            self_propensity = self.get_propensity(prior_propensity)
            if self_propensity is not None and self_propensity < prior_propensity:
                raise ValueError(f'propensity for {prior_propensity} is greater than that for {self_propensity} in {self}')

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check if the prior is an InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Prior is not an InventoryValidator object")

    # Check if the prior has the same number of fields as the current inventory
    if len(self.fields) != len(prior.fields):
        raise ValueError("Prior does not have the same number of fields as the current inventory")

    # Check if the prior fields are the same as the current inventory fields
    for field in self.fields:
        if field not in prior.fields:
            raise ValueError("Prior does not have the same fields as the current inventory")

    # Check if the prior has the same number of constraints as the current inventory
    if len(self.constraints) != len(prior.constraints):
        raise ValueError("Prior does not have the same number of constraints as the current inventory")

    # Check if the prior constraints are the same as the current inventory constraints
    for constraint in self.constraints:
        if constraint not in prior.constraints:
            raise ValueError("Prior does not have the same constraints as the current inventory")

    return True

def validate_as_prior_version(self, prior: "InventoryValidator"):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        return False

    # Check that the prior version has the same variables and parameters
    if set(prior.variables) != set(self.variables):
        return False
    if set(prior.parameters) != set(self.parameters):
        return False

    # Check that the prior version's variables and parameters have the same bounds
    for var in prior.variables:
        if not isinstance(var, Number) or not isinstance(self.variables.get(var), Number):
            return False
        if not self.variables.get(var).bounds == prior.variables.get(var).bounds:
            return False
    for par in prior.parameters:
        if not isinstance(par, Number) or not isinstance(self.parameters.get(par), Number):
            return False
        if not self.parameters.get(par).bounds == prior.parameters.get(par).bounds:
            return False

    # Check that the prior version's model is a submodel of the current model
    if not isinstance(prior.model, Model):
        return False
    if not isinstance(self.model, Model):
        return False
    if not prior.model.is_submodel_of(self.model):
        return False

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Invalid prior object passed for validation.")

    # Check that all parameters in the current inventory also exist in the prior inventory
    for param in self.parameters:
        if param not in prior.parameters:
            raise ValueError(f"Parameter {param} not found in prior inventory.")

    # Check that all species in the current inventory also exist in the prior inventory
    for species in self.species:
        if species not in prior.species:
            raise ValueError(f"Species {species} not found in prior inventory.")

    # Check that all reactions in the current inventory also exist in the prior inventory
    for reaction in self.reactions:
        if reaction not in prior.reactions:
            raise ValueError(f"Reaction {reaction} not found in prior inventory.")

    # Check that the stoichiometry matrices of the current inventory and prior inventory are consistent
    if not np.array_equal(self.stoichiometry_matrix, prior.stoichiometry_matrix):
        raise ValueError("Stoichiometry matrix of current inventory and prior inventory are not consistent.")

    # Check that the propensities of the current inventory and prior inventory are consistent
    if not np.array_equal(self.propensities, prior.propensities):
        raise ValueError("Propensities of current inventory and prior inventory are not consistent.")

    # Check that the initial conditions of the current inventory and prior inventory are consistent
    if not np.array_equal(self.initial_conditions, prior.initial_conditions):
        raise ValueError("Initial conditions of current inventory and prior inventory are not consistent.")

    return True

