    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for record in inventory.get_records(version):
        content_files = record.get(Content.FILE_KEY, [])
        for content_file in content_files:
            logical_path = content_file.get(Content.LOGICAL_PATH_KEY)
            if logical_path:
                if logical_path not in logical_path_map:
