    """
    if platform == 'this':
        platform = '1' if sys.platform.startswith('linux') else '0'

    if platform == '1':
        regex = r'''((?:
            [^\s"']+  # Non-whitespace, non-quoted
            |"[^"]*"  # Double-quoted string
            |'[^']*'  # Single-quoted string
           ))+|(?:\S)'''  # Unquoted, non-whitespace
    else:
        regex = r'''((?:
            [^"\s']+  # Non-whitespace, non-quoted
            |"[^"]*"  # Double-quoted string
