def _split_posix(s):
    """Split a string into a list of arguments for a POSIX shell."""
    args = []
    for arg in re.split(r'(\s+|".*?"|\'.*?\'|\'.*?\')', s):
        arg = arg.strip()
        if arg:
            args.append(arg)
    return args

def _split_nt(s):
    """Split a string into a list of arguments for a Windows/CMD shell."""
    ARGUMENT_PATTERN = re.compile(r'(?:"(?:\\.|[^"])*"|\'(?:\\.|[^\'])*\'|\S+)'
                                  r'(?:(?:(?:\s*(?:&&\s*)?))(?!"|\'| |\t))*',
                                  re.MULTILINE)
    args = []
    for arg in ARGUMENT_PATTERN.findall(s):
        arg = arg.strip()
        if arg:
            args.append(arg)
    return args
