import datetime

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency string")
    try:
        num = int(parts[0])
    except ValueError:
        raise ValueError("Frequency must start with a number")
    if num <= 0:
        raise ValueError("Frequency must be a positive integer")
    unit = parts[1].lower()
    if unit not in ["day", "days", "week", "weeks"]:
        raise ValueError("Frequency must end with a valid time unit (e.g. 'day', 'days', 'week', or 'weeks')")
    if unit.endswith("s"):
        unit = unit[:-1]
    return datetime.timedelta(**{unit: num})
