def identify_request(request):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request.headers.get("Content-Type", "") == "application/json":
        try:
            data = json.loads(request.body)
            if "public" in data and "private" in data:
                return True
        except ValueError:
            pass
    elif request.headers.get("Content-Type", "") == "application/xml":
        try:
            xml = etree.fromstring(request.body)
            if xml.tag == "diaspora":
                return True
        except etree.XMLSyntaxError:
            pass
    return False

