def xml_to_dict(root_element):
    """
    Convert an XML ElementTree to a dictionary

    Args:
        root_element: The root XML element of the tree

    Returns:
        A dictionary of the XML structure, keyed by tag name
    """
    result = {}

    # Add attributes to the result if the root element has any
    if root_element.attrib:
        result.update(root_element.attrib)

    # Add children nodes to the result if the root element has any
    for child in root_element:
        # Elements with the same tag name get aggregated into a list
        if child.tag in result:
            if type(result[child.tag]) is not list:
                result[child.tag] = [result[child.tag]]
            result[child.tag].append(xml_to_dict(child))
        else:
            result[child.tag] = xml_to_dict(child)

    # Add the element text to the result
    if root_element.text is not None:
        result["text"] = root_element.text.strip()

    return result

