def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        json_data = json.loads(document)
        return json_data
    except json.decoder.JSONDecodeError:
        pass

    try:
        xml_doc = ET.fromstring(document)
    except ET.ParseError:
        return None

    namespace = "http://docs.oasis-open.org/ns/xri/xrd-1.0"
    xrd = xml_doc.find("{%s}XRD" % namespace)
    if xrd is None:
        return None

    aliases = []
    properties = {}
    links = {}
    for child in xrd.findall(".//{%s}*[not(%s) and not(%s)]" % (
        namespace,
        "{%s}Subject" % namespace,
        "{%s}Link" % namespace,
    )):
        tag = child.tag.split("}", 1)[-1]
        value = child.text
        if tag == "Alias":
            aliases.append(value)
        elif tag == "Property":
            properties[value.get("type")] = value.text
        elif tag == "Link":
            links[value.get("rel")] = value.get("href")

    return {"aliases": aliases, "properties": properties, "links": links}

